@@ -0,0 +1,29 @@
+// Sites (kitchens). Every location belongs to one site; batches belong to
+// the site of their location. Items, suppliers, recipes and dishes are shared.
+import { AppError } from "../errors.js";
+
+export const DEFAULT_SITE = "main";
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = (store.data.sites ?? []).find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** Locations of a site (every location when `site` is undefined). */
+export function siteLocations(store, site) {
+  return store.data.locations.filter((l) => site === undefined || l.site === site);
+}
+
+/** True when a location id belongs to the site (any site when `site` is undefined). */
+export function locationInSite(store, location, site) {
+  return siteLocations(store, site).some((l) => l.id === location);
+}
+
+/** Batches stored in a site (every batch when `site` is undefined). */
+export function siteBatches(store, site) {
+  if (site === undefined) return store.data.batches;
+  const ids = new Set(siteLocations(store, site).map((l) => l.id));
+  return store.data.batches.filter((b) => ids.has(b.location));
+}
