+import test from "node:test";
+import assert from "node:assert/strict";
+import { app } from "./helpers.js";
+
+const ANNEX = { "X-Larder-Site": "annex" };
+
+// Puts 3 l of milk (item 2) into the annex fridge through an order.
+async function stockAnnex(handle) {
+  const order = (await handle({ method: "POST", path: "/orders", body: { supplierId: 2, lines: [{ itemId: 2, qty: 3 }] } })).body;
+  await handle({ method: "POST", path: `/orders/${order.id}/send` });
+  return handle({ method: "POST", path: `/orders/${order.id}/receive`, headers: ANNEX, body: { lots: [{ lot: "HD-A1", expires: "2026-10-30", location: "annex-fridge" }] } });
+}
+
+test("without the header the site is main; an unknown site is a 400", async () => {
+  const { handle } = app();
+  const main = await handle({ path: "/items", headers: { "x-larder-site": "main" } });
+  assert.deepEqual(main.body, (await handle({ path: "/items" })).body);
+  const bad = await handle({ path: "/items", headers: { "x-larder-site": "attic" } });
+  assert.equal(bad.status, 400);
+  assert.equal(bad.body.error.code, "unknown_site");
+  assert.match(bad.body.error.message, /attic/);
+});
+
+test("stock, batches and reports only see the request's site", async () => {
+  const { handle } = app();
+  const received = await stockAnnex(handle);
+  assert.equal(received.status, 200);
+  const batchId = received.body.batches[0].id;
+
+  const items = (await handle({ path: "/items", headers: ANNEX })).body;
+  assert.equal(items.length, 6);
+  assert.equal(items.find((i) => i.id === 2).onHand, 3);
+  assert.equal(items.find((i) => i.id === 1).onHand, 0);
+  assert.equal((await handle({ path: "/items" })).body.find((i) => i.id === 2).onHand, 10);
+
+  assert.deepEqual((await handle({ path: "/batches", headers: ANNEX })).body.map((b) => b.id), [batchId]);
+  assert.ok(!(await handle({ path: "/batches" })).body.some((b) => b.id === batchId));
+  assert.equal((await handle({ path: `/batches/${batchId}` })).status, 404);
+  assert.equal((await handle({ path: "/batches/1", headers: ANNEX })).status, 404);
+  assert.equal((await handle({ method: "POST", path: "/batches/1/waste", headers: ANNEX, body: { qty: 1 } })).status, 404);
+
+  assert.equal((await handle({ path: "/reports/stock-value", headers: ANNEX })).body.totalCents, 3 * 129);
+  const alerts = (await handle({ path: "/alerts", headers: ANNEX })).body;
+  assert.deepEqual(alerts.expiring.map((b) => b.lot), ["HD-A1"]);
+  assert.ok(alerts.lowStock.some((l) => l.itemId === 1));
+  assert.match((await handle({ path: "/export/stock.csv", headers: ANNEX })).body, /\nDAI-MILK,milk,l,3,6\n/);
+});
+
+test("cooking uses only the request's site", async () => {
+  const { handle, store } = app();
+  const before = JSON.stringify(store.data.batches);
+  const res = await handle({ method: "POST", path: "/recipes/2/cook", headers: ANNEX, body: { portions: 1 } });
+  assert.equal(res.status, 409);
+  assert.equal(JSON.stringify(store.data.batches), before);
+});
+
+test("orders are received into a location of the request's site", async () => {
+  const { handle } = app();
+  const order = (await handle({ method: "POST", path: "/orders", body: { supplierId: 2, lines: [{ itemId: 2, qty: 3 }] } })).body;
+  await handle({ method: "POST", path: `/orders/${order.id}/send` });
+  const res = await handle({ method: "POST", path: `/orders/${order.id}/receive`, body: { lots: [{ lot: "x", expires: null, location: "annex-fridge" }] } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_location");
+});
+
+test("stock-takes only see the request's site", async () => {
+  const { handle } = app();
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", headers: ANNEX, body: { location: "dry" } })).status, 400);
+  const take = (await handle({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: ANNEX, body: { batchId: 6, counted: 12 } })).status, 404);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: ANNEX })).status, 404);
+  const annex = await handle({ method: "POST", path: "/stocktakes", headers: ANNEX, body: { location: "annex-fridge" } });
+  assert.equal(annex.status, 201);
+});
+
+test("items, recipes and dishes are shared", async () => {
