+  assert.equal((await handle({ path: "/items/1", headers: ANNEX })).body.name, "onion");
+  assert.deepEqual((await handle({ path: "/dishes", headers: ANNEX })).body, (await handle({ path: "/dishes" })).body);
+  assert.deepEqual((await handle({ path: "/recipes/1/cost", headers: ANNEX })).body, (await handle({ path: "/recipes/1/cost" })).body);
+});
